package com.company.skillplatform.user.application;
import com.company.skillplatform.user.domain.UserStatus;import com.company.skillplatform.user.infrastructure.entity.IamUserEntity;import com.company.skillplatform.user.infrastructure.repository.IamUserRepository;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class UserCandidateService{private final IamUserRepository users;public UserCandidateService(IamUserRepository users){this.users=users;}@PreAuthorize("hasAnyAuthority('skill:edit','admin:identity')")@Transactional(readOnly=true)public Page<CandidateView> search(String keyword,Pageable pageable){Pageable limited=PageRequest.of(pageable.getPageNumber(),Math.min(pageable.getPageSize(),50),pageable.getSort());Specification<IamUserEntity> spec=(root,q,cb)->{var active=cb.equal(root.get("status"),UserStatus.ACTIVE);if(keyword==null||keyword.isBlank())return active;String value="%"+keyword.toLowerCase(Locale.ROOT)+"%";return cb.and(active,cb.or(cb.like(cb.lower(root.get("username")),value),cb.like(cb.lower(root.get("displayName")),value)));};return users.findAll(spec,limited).map(u->new CandidateView(u.getId(),u.getUsername(),u.getDisplayName(),u.getStatus()));}public record CandidateView(Long id,String username,String displayName,UserStatus status){} }
